  lemma InitSatisfiesInv()
    ensures Inv(Init())
  {
  }

  lemma StepPreservesInv(m: Model, a: Action)
    ensures Inv(Normalize(Apply(m, a)))
  {
  }

  lemma LoginSucceeds(m: Model, a: Action)
    requires a == Login("alice", "secret")
    ensures (Apply(m, a)).0
